class Coin(int cents) { public int Cents = cents; }
class Groups {
 public List<Set<Reference<Coin>>> Sets = [];
 public Dictionary<string, Set<Reference<Coin>>> Map = {};
 public List<Set<Reference<int>>> Slots = [];
 public List<Set<Reference<List<int>>>> Collections = [];
}
@storage(allowed: .Immutable)
class FrozenGroups {
 public List<Set<Reference<Coin>>> Sets = [[]];
 public Dictionary<string, Set<Reference<Coin>>> Map = {"first": []};
 public List<Set<Reference<int>>> Slots = [[]];
 public List<Set<Reference<List<int>>>> Collections = [[]];
}
class Constrained<T extends Coin> {
 public List<Set<Reference<T>>> Picks = [[]];
 public Dictionary<string, Set<Reference<T>>> Map = {"first": []};
}
class Probe {
 @storage(allowed: .Session) public static Groups Saved = new();
 @storage(allowed: .Immutable) public static FrozenGroups Frozen = new();
 @storage(allowed: .Immutable) public static Groups Asset = new();
 @storage(allowed: .Session) public static Constrained<Coin> Bound = new();
 @storage(allowed: .Immutable) public static Coin FrozenCoin = new Coin(11);
 @storage(allowed: .Session) public static Coin LiveCoin = new Coin(3);
 public static Groups Make() => new Groups();
 public static int Empty() => new Groups().Sets.Count;
}
